                AccessKeyID:     "{{$AccessKeyID}}",     // 点击头像 -> 账号中心 -> 密钥管理
                SecretAccessKey: "{{$SecretAccessKey}}", // 点击头像 -> 账号中心 -> 密钥管理
                Region:          "{{$Region}}",          // 默认，没特殊要求就用这个:cn-north-1
                Service:         "{{$ServiceName}}",     // 调用服务名
        }
        httpTimeOut = 5 * time.Second
)

func Request(action, version string, body any, query string) ([]byte, error) {
        requesturl := fmt.Sprintf("%s?Action=%s&Version=%s&X-Account-Id=%d", topHost, action, version, accountID)
        if query != "" {
                if !strings.HasPrefix(query, "/") {
                        query = "&" + query
                }
                requesturl += query
        }
        b, _ := json.Marshal(body)

        req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, requesturl, bytes.NewBuffer(b))
        req.Header.Set("Content-Type", "application/json")

        req = signer.Sign(req)
        httpClient := &http.Client{
                Timeout: httpTimeOut,
        }

        /* do request and get return */
        rawResp, err := httpClient.Do(req)
        if err != nil {
                return nil, err
        } else {
                resp, err := io.ReadAll(rawResp.Body)
                if err != nil {
                        return nil, err
                }

                code := rawResp.StatusCode

                if code != http.StatusOK {
                        return nil, fmt.Errorf(string(resp))
                }
                return resp, nil
        }
}

