import json
import requests
import datetime
from cryptography.hazmat.primitives import hashes, hmac
from urllib.parse import quote

class TopAPICallException(Exception):
    pass

class HTTPClient:
    def __init__(
        self, host: str, region: str, service: str, ak: str, sk: str, use_sm: bool
    ) -> None:
        self.host = host
        self.region = region
        self.service = service
        self.ak = ak
        self.sk = sk
        self.use_sm = use_sm

    def post(self, action: str, version: str, req: dict, tenant_id: str) -> str:
        headers = {
            "Content-Type": "application/json",
            "X-Tenant-Id": str(tenant_id),
            "X-Top-Tenant-Id": str(tenant_id),
        }
        query = {
            "Action": action,
            "Version": version,
            "X-Tenant-Id": str(tenant_id),
        }
        body = json.dumps(req)

        SignerV4.sign(
            path="/",
            method="POST",
            headers=headers,
            body=body,
            query=query,
            ak=self.ak,
            sk=self.sk,
            service=self.service,
            region=self.region,
            use_sm=self.use_sm,
        )

        resp = requests.post(
            url=self.host,
            headers=headers,
            params=query,
            data=body,
        )

        if resp.status_code >= 300:
            raise TopAPICallException(
                f"request error, action: {action}, status code: {resp.status_code}, body: {resp.text}",
            )

        return resp.text

    def createWorkspace(self, req: dict, tenant_id: str) :
        resp = client.post(
                action="CreateWorkspaceForAdmin",
                version="2024-12-25",
                req=req,
                tenant_id=tenant_id,
            )
        print(resp)

    def deleteWorkspace(self, req: dict, tenant_id: str) :
        resp = client.post(
                action="DeleteWorkspace",
                version="2024-12-25",
                req=req,
                tenant_id=tenant_id,
            )
        print(resp)

class SignerV4(object):
    @staticmethod
    def sign(
        path,
        method,
        headers,
        body,
        query,
        ak,
        sk,
        region,
        service,
        use_sm: bool = False,
    ):
        if path == "":
            path = "/"
        if method != "GET" and not (
            "Content-Type" in headers or "content-type" in headers
        ):
            headers["Content-Type"] = "application/x-www-form-urlencoded; charset=utf-8"
        format_date = datetime.datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
        headers["X-Date"] = format_date

        body_hash = SignerV4.hashSum(body.encode("utf-8"), use_sm).hex()
        headers["X-Content-Sha256"] = body_hash

        signed_headers = dict()
        for key in headers:
            if key in [
                "Content-Type",
                "content-type",
                "Content-Md5",
                "Host",
            ] or key.startswith("X-"):
                signed_headers[key.lower()] = headers[key]

        if "host" in signed_headers:
            v = signed_headers["host"]
            if v.find(":") != -1:
                split = v.split(":")
                port = split[1]
                if str(port) == "80" or str(port) == "443":
                    signed_headers["host"] = split[0]

        signed_str = ""
        for key in sorted(signed_headers.keys()):
            signed_str += key + ":" + signed_headers[key] + "\n"

        signed_headers_string = ";".join(sorted(signed_headers.keys()))

        canonical_request = "\n".join(
            [
                method,
                path,
                SignerV4.canonical_query(dict(query)),
                signed_str,
                signed_headers_string,
                body_hash,
            ]
        )
        credential_scope = "/".join([format_date[:8], region, service, "request"])
        signing_str = "\n".join(
            [
                "HMAC-SHA256",
                format_date,
                credential_scope,
                SignerV4.hashSum(canonical_request.encode("utf-8"), use_sm).hex(),
            ]
        )
        signing_key = SignerV4.get_signing_secret_key_v4(
            sk, format_date[:8], region, service, use_sm
        )

        signature = SignerV4.hmac_sum(
            signing_key, signing_str.encode("utf-8"), use_sm
        ).hex()

        credential = ak + "/" + credential_scope
        headers["Authorization"] = (
            "HMAC-SHA256"
            + " Credential="
            + credential
            + ", SignedHeaders="
            + signed_headers_string
            + ", Signature="
            + signature
        )
        return

    @staticmethod
    def canonical_query(query):
        res = []
        for key in query:
            value = str(query[key])
            res.append((quote(key, safe="-_.~"), quote(value, safe="-_.~")))
        sorted_key_vals = []
        for key, value in sorted(res):
            sorted_key_vals.append("%s=%s" % (key, value))
        return "&".join(sorted_key_vals)

    @staticmethod
    def get_signing_secret_key_v4(sk, date, region, service, use_sm: bool = False):
        kdate = SignerV4.hmac_sum(sk.encode("utf-8"), date.encode("utf-8"), use_sm)
        kregion = SignerV4.hmac_sum(kdate, region.encode("utf-8"), use_sm)
        kservice = SignerV4.hmac_sum(kregion, service.encode("utf-8"), use_sm)
        return SignerV4.hmac_sum(kservice, "request".encode("utf-8"), use_sm)

    @staticmethod
    def hmac_sum(key: bytes, msg: bytes, use_sm: bool = False):
        hasher = hashes.SHA256()
        if use_sm:
            hasher = hashes.SM3()
        h = hmac.HMAC(key, hasher)
        h.update(msg)
        return h.finalize()

    @staticmethod
    def hashSum(msg: bytes, use_sm: bool = False):
        hasher = hashes.SHA256()
        if use_sm:
            hasher = hashes.SM3()
        digest = hashes.Hash(hasher)
        digest.update(msg)
        return digest.finalize()

