            this.httpClient = HttpClient.newHttpClient();
        }

        /**
         * Makes a POST request to the API.
         * @param action The API action.
         * @param version The API version.
         * @param req The request payload.
         * @param tenantId The tenant ID.
         * @return The response body as a string.
         * @throws TopAPICallException if the API call fails.
         */
        public String post(String action, String version, Map<String, Object> req, String tenantId) throws TopAPICallException {
            try {
                Map<String, String> headers = new TreeMap<>();
                headers.put("Content-Type", "application/json");
                headers.put("X-Tenant-Id", tenantId);
                headers.put("X-Top-Tenant-Id", tenantId);

                Map<String, String> query = new TreeMap<>();
                query.put("Action", action);
                query.put("Version", version);
                query.put("X-Tenant-Id", tenantId);

                String body = gson.toJson(req);

                SignerV4.sign(
                        "/",
                        "POST",
                        headers,
                        body,
                        query,
                        this.ak,
                        this.sk,
                        this.region,
                        this.service,
                        this.useSm
                );

                String queryString = SignerV4.canonicalQuery(query);
                URI uri = URI.create(this.host + "?" + queryString);

                HttpRequest.Builder httpRequestBuilder = HttpRequest.newBuilder()
                        .uri(uri)
                        .POST(HttpRequest.BodyPublishers.ofString(body, StandardCharsets.UTF_8));

                headers.forEach(httpRequestBuilder::header);

                HttpResponse<String> response = httpClient.send(httpRequestBuilder.build(), HttpResponse.BodyHandlers.ofString());

                if (response.statusCode() >= 300) {
                    throw new TopAPICallException(
                            String.format("request error, action: %s, status code: %d, body: %s",
                                    action, response.statusCode(), response.body())
                    );
                }

                return response.body();
            } catch (Exception e) {
                throw new TopAPICallException("Failed to make POST request: " + e.getMessage());
            }
        }

        /**
         * Creates a workspace by calling the "CreateWorkspaceForAdmin" action.
         * @param req The request payload.
         * @param tenantId The tenant ID.
         * @throws TopAPICallException if the API call fails.
