    /**
     * Implements the signing process.
     */
    public static class SignerV4 {

        private static final DateTimeFormatter yyyyMMddTHHmmssZ = DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'");

        /**
         * Signs the request and adds the "Authorization" header.
         */
        public static void sign(String path, String method, Map<String, String> headers, String body,
                                Map<String, String> query, String ak, String sk, String region,
                                String service, boolean useSm) throws NoSuchAlgorithmException, InvalidKeyException {

            if (path == null || path.isEmpty()) {
                path = "/";
            }
            if (!"GET".equals(method) && headers.keySet().stream().noneMatch(k -> k.equalsIgnoreCase("Content-Type"))) {
                headers.put("Content-Type", "application/x-www-form-urlencoded; charset=utf-8");
            }

            String format_date = ZonedDateTime.now(ZoneOffset.UTC).format(yyyyMMddTHHmmssZ);
            headers.put("X-Date", format_date);

            String bodyHash = bytesToHex(hashSum(body.getBytes(StandardCharsets.UTF_8), useSm));
            headers.put("X-Content-Sha256", bodyHash);

            Map<String, String> signedHeaders = new TreeMap<>();
            for (Map.Entry<String, String> entry : headers.entrySet()) {
                String key = entry.getKey();
                if (key.equalsIgnoreCase("Content-Type") ||
                    key.equalsIgnoreCase("Content-Md5") ||
                    key.equalsIgnoreCase("Host") ||
                    key.toLowerCase().startsWith("x-")) {
                    signedHeaders.put(key.toLowerCase(), entry.getValue());
                }
            }

            if (signedHeaders.containsKey("host")) {
                String v = signedHeaders.get("host");
                if (v.contains(":")) {
                    String[] split = v.split(":");
                    String port = split[1];
                    if ("80".equals(port) || "443".equals(port)) {
                        signedHeaders.put("host", split[0]);
                    }
                }
            }

            StringBuilder signedStrBuilder = new StringBuilder();
            for (Map.Entry<String, String> entry : signedHeaders.entrySet()) {
                signedStrBuilder.append(entry.getKey()).append(":").append(entry.getValue()).append("\n");
            }

            String signedHeadersString = String.join(";", signedHeaders.keySet());

            String canonicalRequest = String.join("\n",
                    method,
                    path,
                    canonicalQuery(query),
                    signedStrBuilder.toString(),
                    signedHeadersString,
                    bodyHash
            );

            String credentialScope = String.join("/", format_date.substring(0, 8), region, service, "request");
            String signingStr = String.join("\n",
                     "HMAC-SHA256",
                    format_date,
                    credentialScope,
                    bytesToHex(hashSum(canonicalRequest.getBytes(StandardCharsets.UTF_8), useSm))
            );

            byte[] signingKey = getSigningSecretKeyV4(sk, format_date.substring(0, 8), region, service, useSm);
            String signature = bytesToHex(hmacSum(signingKey, signingStr.getBytes(StandardCharsets.UTF_8), useSm));

            String credential = ak + "/" + credentialScope;
            String authorization = ("HMAC-SHA256") +
                    " Credential=" + credential +
                    ", SignedHeaders=" + signedHeadersString +
                    ", Signature=" + signature;
            headers.put("Authorization", authorization);
        }

        /**
         * Creates a canonical query string from a map of query parameters.
         */
        public static String canonicalQuery(Map<String, String> query) {
            if (query == null || query.isEmpty()) {
                return "";
            }
            return query.entrySet().stream()
                    .sorted(Map.Entry.comparingByKey())
                    .map(e -> urlEncode(e.getKey()) + "=" + urlEncode(e.getValue()))
                    .collect(Collectors.joining("&"));
        }

        private static String urlEncode(String value) {
            try {
                return URLEncoder.encode(value, StandardCharsets.UTF_8.name())
                        .replace("+", "%20")
                        .replace("*", "%2A")
                        .replace("%7E", "~");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        /**
         * Derives the signing key for Signature Version 4.
         */
        private static byte[] getSigningSecretKeyV4(String sk, String date, String region, String service, boolean useSm) throws InvalidKeyException, NoSuchAlgorithmException {
            byte[] kDate = hmacSum(sk.getBytes(StandardCharsets.UTF_8), date.getBytes(StandardCharsets.UTF_8), useSm);
            byte[] kRegion = hmacSum(kDate, region.getBytes(StandardCharsets.UTF_8), useSm);
            byte[] kService = hmacSum(kRegion, service.getBytes(StandardCharsets.UTF_8), useSm);
            return hmacSum(kService, "request".getBytes(StandardCharsets.UTF_8), useSm);
        }

        /**
         * Calculates HMAC signature.
         */
        private static byte[] hmacSum(byte[] key, byte[] msg, boolean useSm) throws NoSuchAlgorithmException, InvalidKeyException {
            String alg = useSm ? "HmacSM3" : "HmacSHA256";
            Mac mac = Mac.getInstance(alg);
            mac.init(new SecretKeySpec(key, alg));
            return mac.doFinal(msg);
        }

        /**
         * Calculates a hash (SHA-256 or SM3).
         */
        private static byte[] hashSum(byte[] msg, boolean useSm) throws NoSuchAlgorithmException {
            String alg = useSm ? "SM3" : "SHA-256";
            MessageDigest digest = MessageDigest.getInstance(alg);
            return digest.digest(msg);
        }

        private static final char[] HEX_ARRAY = "0123456789abcdef".toCharArray();

        /**
         * Converts a byte array to a hexadecimal string.
         */
        public static String bytesToHex(byte[] bytes) {
            char[] hexChars = new char[bytes.length * 2];
            for (int j = 0; j < bytes.length; j++) {
                int v = bytes[j] & 0xFF;
                hexChars[j * 2] = HEX_ARRAY[v >>> 4];
                hexChars[j * 2 + 1] = HEX_ARRAY[v & 0x0F];
            }
            return new String(hexChars);
        }
    }

