    req = c.ServiceInfo.Credentials.Sign(req).WithContext(ctx)

    resp, err := c.Client.Do(req) // nolint
    if err != nil {
       return []byte(""), 500, err
    }
    defer func(Body io.ReadCloser) {
       err := Body.Close()
       if err != nil {
          print("failed to close response body")
       }
    }(resp.Body)
    body, err := io.ReadAll(resp.Body)
    if err != nil {
       return []byte(""), resp.StatusCode, err
    }

    if resp.StatusCode != http.StatusOK {
       return body, resp.StatusCode, fmt.Errorf("uri %s http code %d body %s", req.RequestURI, resp.StatusCode, string(body))
