golang
type UpService struct {
        UpHost   string
        DownHost string
}

type UploadRawResult struct {
        Path   string `json:"Path"`
        Sha256 string `json:"Sha256"`
        Size   int    `json:"Size"`
}

type UploadRawResponse struct {
        Result UploadRawResult `json:"Result"`
}

func (u *UpService) UploadRaw(filePath, hashSum string) (path string, err error) {
        fileData, err := ioutil.ReadFile(filePath)
        if err != nil {
                return
        }

        url := fmt.Sprintf("%s/up?Action=UploadRaw&Version=2022-01-01&Id=example", u.UpHost)
        req, err := http.NewRequest("POST", url, bytes.NewBuffer(fileData))
        if err != nil {
                return
        }

        req.Header.Set("Content-Type", "application/json")
        req.Header.Set("X-Content-Sha256", hashSum)

        client := &http.Client{}
        resp, err := client.Do(req)
        if err != nil {
                return
        }
        defer resp.Body.Close()

        if resp.StatusCode != http.StatusOK {
                return "", fmt.Errorf("Failed to UploadRaw file: status code %d", resp.StatusCode)
        }

        body, err := ioutil.ReadAll(resp.Body)
        if err != nil {
                return
        }

        var response UploadRawResponse
        err = json.Unmarshal(body, &response)
        if err != nil {
                return
        }

        return response.Result.Path, nil
}

func (u *UpService) Download(path, key string) error {
        url := fmt.Sprintf("%s/down?Action=Download&Version=2022-01-01&Path=%s&Key=%s", u.DownHost, path, key)

        resp, err := http.Get(url)
        if err != nil {
                return err
        }
        defer resp.Body.Close()

        if resp.StatusCode != http.StatusOK {
                return fmt.Errorf("Failed to download file: status code %d", resp.StatusCode)
        }

        outFile, err := os.Create("downloaded_file.txt")
        if err != nil {
                return err
        }
        defer outFile.Close()

        _, err = io.Copy(outFile, resp.Body)
        if err != nil {
                return err
        }

        log.Println("File downloaded successfully!")
        return nil
}

type DownloadKeyResult struct {
        Key string `json:"Key"`
}

type DownloadKeyResponse struct {
        Result DownloadKeyResult `json:"Result"`
}

func (u *UpService) DownloadKey(path string) (key string, err error) {
        url := fmt.Sprintf("%s/up?Action=DownloadKey&Version=2022-01-01&Path=%s", u.UpHost, path)

        req, err := http.NewRequest("POST", url, nil)
        if err != nil {
                return
        }

        client := &http.Client{}
        resp, err := client.Do(req)
        if err != nil {
                return
        }
        defer resp.Body.Close()

        if resp.StatusCode != http.StatusOK {
                return "", fmt.Errorf("Failed to DownloadKey: status code %d", resp.StatusCode)
        }

        body, err := ioutil.ReadAll(resp.Body)
        if err != nil {
                return
        }

        var response DownloadKeyResponse
        err = json.Unmarshal(body, &response)
        if err != nil {
                return
        }

        return response.Result.Key, nil
}

func main() {
        u := &UpService{
                UpHost:   "http://x.x.x.x:31010",
                DownHost: "http://x.x.x.x:31011",
        }
        filePath := "/Users/bytedance/Downloads/大熊猫的故事.txt"
        hashSum := "xxxxxx"

        path, err := u.UploadRaw(filePath, hashSum)
        if err != nil {
                fmt.Println("UploadRaw failed", err)
                return
        }

        key, err := u.DownloadKey(path)
        if err != nil {
                fmt.Println("DownloadKey failed", err)
                return
        }

        err = u.Download(path, key)
        if err != nil {
                fmt.Println("Download failed", err)
                return
        }
}
