development-guide/frontend-customization:
#
HiAgent平台前端页面嵌入已有平台
#
背景

客户希望将HiAgent整体、智能体WEB对话页，或者任何前端页面嵌入到已有的门户网站平台时，可以参考此文档完成开发。

❗ 适用于HiAgent 2.0.0及之后的版本

#
步骤

使用 iframe 方式嵌入 HiAgent 平台

打通SSO避免二次登录（推荐） 完成 sso 对接，并开启强制 sso 登录

按需接入SSO用户登出、导航栏隐藏等

#
开发指南
#
嵌入到目标平台

使用 iframe 方式嵌入 HiAgent 平台

<body>
  <iframe src="http://x.x.x.x:x"></iframe>
</body>
#
避免二次登录

只要满足以下条件，即可实现免密二次登录

SSO接入后开启强制跳转SSO登录页

保证 HiAgent 服务和主服务同协议，同主域名/IP

2.0.0 版本只支持单租户开启强制 SSO，2.0.1 版本支持多租户开启强制 SSO

租户管理员进入平台管理端->第三方认证开启SSO



存存在跨域问题，请参考第4章节《跨域问题解决方案》
#
跨域问题解决方案
#
增加二级域名

假如用户服务地址是 http://a.test.com，HiAgent 服务地址是 http://hiagent.com，当用户以 iframe 嵌入 HiAgent 服务时，会产生跨域问题，影响 cookie 传递，主要包含 2 个 cookie

tenant （统一平台身份 cookie）
x-csrf-token （防止请求伪造 cookie）
#
请求过程

#
使用 nginx 等反向代理转发 HiAgent
保证转发后的 HiAgent 服务和主服务同协议，同主域名/IP

嵌入 HiAgent 地址

主服务地址

nginx 需要打开转发下划线 header，并开启流式输出
server {
    listen 8998;
    # listen 8999 ssl;
    server_name  a.test.com;
    # ssl_certificate ssl/server.crt;
    # ssl_certificate_key ssl/server.key;
    # ssl_ciphers HIGH:!aNULL:!MD5;    
    # ssl_protocols SSLv2 TLSv1 TLSv1.2;

    # 转发下划线 header
    underscores_in_headers on;
    # 开启流式输出
    proxy_cache off;
    proxy_buffering off;
    keepalive_timeout 300;

    location / {
        proxy_pass http://xxx.xxx.xxx.xxx:xxxx;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Host $http_host;
        proxy_set_header X-Forwarded-Proto $scheme;

        # 移除原有的安全头
        proxy_hide_header X-Frame-Options;
        proxy_hide_header Content-Security-Policy;

        # 添加允许iframe嵌入的头, iframe 场景使用
        add_header X-Frame-Options "ALLOW-FROM [http://](http://www.genaimap.cn)[your domain]" always;
        add_header Content-Security-Policy "frame-ancestors 'self' [http://](http://www.genaimap.cn)[your domain]" always;
        # 如果是 SSL场景，上面这行不用，换成下面这行，区别在于红色标注区域：
        add_header Content-Security-Policy "upgrade-insecure-requests; frame-ancestors 'self' [http://](http://www.genaimap.cn)[your domain]" always;
    }

    # onlyoffice websocket 转发配置

    # 测试方法：去知识库上传一个word/ppt/excel/pdf，然后点击在线查看观察是否能正常载入文档
    # v2.0.0
    location /resources/product/onlyoffice/8.0.1-31/doc {
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Host $http_host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "upgrade";
        proxy_pass http://xxx.xxx.xxx.xxx:xxxx/resources/product/onlyoffice/8.0.1-31/doc;
    }

    # v2.0.1+
    location ~ ^/resources/product/onlyoffice/([^/]+)/doc {
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Host $http_host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_pass http://xxx.xxx.xxx.xxx:xxxx;
    }

    # v2.1.0+
    location ~ ^/api/proxy/cloud/ws {
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Host $http_host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_pass http://xxx.xxx.xxx.xxx:xxxx;
    }

    # v2.4.0+
    location ~ ^/api/proxy/aigw/v1 {
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Host $http_host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_pass http://xxx.xxx.xxx.xxx:xxxx;
    }

}
#
允许跨站携带 cookie（hiagent 服务必须是 https，有一定安全风险）
#
IIS

确保安装

https://www.iis.net/downloads/microsoft/url-rewrite
https://www.iis.net/downloads/microsoft/application-request-routing
<!-- web.config 配置 -->
<?xml version="1.0" encoding="utf-8"?>
<configuration>
  <system.webServer>
    <rewrite>

      <!-- 入站规则：先处理 CORS 预检，再执行反向代理 -->
      <rules>
        <!-- 其余请求统一反向代理到后端服务，保持既有反向代理功能 -->
        <rule name="ReverseProxyToBackend" stopProcessing="true">
          <match url="(.*)" />
          <action type="Rewrite" url="HiAgent 平台用户端地址/{R:1}" logRewrittenUrl="true" />
        </rule>
      </rules>

      <!-- 出站规则：设置 Cookie SameSite 重写 -->
      <outboundRules>
        <preConditions>

          <!-- 仅当响应中包含 SameSite 字段时才重写 Set-Cookie -->
          <preCondition name="HasSameSite">
            <add input="{RESPONSE_Set_Cookie}" pattern="; SameSite=" ignoreCase="true" />
          </preCondition>
        </preConditions>

        <!-- Cookie SameSite：将 Lax/Strict 统一改为 None，并追加 Secure（仅当存在 SameSite 字段时） -->
        <rule name="ForceSameSiteNoneForCookies" preCondition="HasSameSite" stopProcessing="false">
          <match serverVariable="RESPONSE_Set_Cookie" pattern="(.*SameSite=)(Lax|Strict)(.*)" ignoreCase="true" />
          <action type="Rewrite" value="{R:1}None{R:3}; Secure" />
        </rule>
      </outboundRules>
    </rewrite>
  </system.webServer>
</configuration>
#
Nginx 1.19.3+
# nginx.conf 或 site config
location / {
    proxy_pass http://hiagent_server;

    # 修改所有 Cookie，追加 SameSite=None 和 Secure 标志
    proxy_cookie_flags ~ secure samesite=none;
}
#
用户同步和记录最后访问地址（可选）
#
修改 configs.yaml 配置文件
# config.yaml
platform:
  customconfig:
    app:
      llmWeb:
        VIEW_MODE:
          enableIframe: true # 是否启用 IFrame 相关能力
#
术语
Platform侧（客户侧负责）：产品整体，包含登录功能，包含智能对话、文库助手、AI Agent等标签页
Agent侧（BD负责）：AI Agent 标签页 IFrame 内的内嵌应用
#
iframe 内 url 改变通知外部，缓存到外部上下文，外部应用切换到其他页面再返回后，可以回到缓存的 url 而不是首页
#
流程
Agent 侧监听 IFrame 的 url 变化
每发生一次变化，通过 parent.postMessage 向 Platform 侧发送最新的 url 数据
Platform 侧监听所有 message
区分消息类型，消息为 Agent URL 改变(type: 'AI_AGENT_URL_CHANGE')类型时，提取 url 数据并保存到全局状态管理
Platform 侧切换页面
打开 AI Agent 页面，从全局状态管理内检查和提取之前保存的 url 数据
如果没有，使用默认域名组装 IFrame 打开 Agent 侧
如果有，使用存储到 url 组装 IFrame 打开 Agent 侧
#
iframe 外侧退出登录，换另一个用户登录，iframe 内部可以同步以另一个用户身份操作 AI Agent 功能
#
流程
Agent 侧监听所有 message
区分消息类型,消息类型为(type: 'AI_AGENT_ME_INFO')时，提取 me 数据
将 Platform 侧反馈的数据和当前登录用户数据匹配
如果相同，则不做调整
如果不同，则退出登录后使用 Platform 侧的用户信息重新登录
没有返回用户信息，退出登录
Agent 侧页面渲染完成，通过 parent.postMessage 发送消息，要求 Platform 侧当前登录用户
消息类型(type: 'AI_AGENT_ME_INFO')通知 Platform 侧，要求反馈 Platform 侧当前登录用户的标识
Platform 侧监听所有 message
区分消息类型，消息为 Agent URL 改变(type: 'AI_AGENT_ME_INFO')类型时，提取当前登录用户信息，通过 postMessage 发送消息
Platform 侧退出登录
主动通过 postMessage 广播消息(type: 'AI_AGENT_ME_INFO')，不传用户信息
触发时机：退出登录时
#
接口参考
